package dev.fluidgore.anatomy;

/**
 * A sheep's data sheet as the mod reads it, generated by {@code tools/SheepAnatomyModels.java} from
 * {@code sheets/sheep.sheet}: do not edit, change the sheet and run the tool again.
 * {@code docs/sheets/sheep.md} is the same sheet for people, with every part of the animal and the reference
 * each number was read from.
 */
public final class SheepSheet {
	/**
	 * The grown animal's live weight, kilograms.
	 * Butterfield (1988), Table 4.b.1, p. 81: liveweight of mature Merino ewes, N = 16 (shorn full liveweight, Table 4.b.2).
	 */
	public static final float LIVE_KG = 49.0F;
	/**
	 * The blood in its body, millilitres a kilogram of live weight.
	 * Hansard (1956), Table I: total blood volume of yearling sheep, 5.9 ml per 100 g body weight, N = 8, mean 118 lb, by red cells labelled with phosphorus-32.
	 */
	public static final float BLOOD_ML_PER_KG = 59.0F;

	private SheepSheet() {
	}
}
